{
  "name": "@omniroute/opencode-plugin-v2",
  "version": "0.1.0",
  "description": "OmniRoute OpenCode plugin (v2 Promise API): catalog transform with models, combos, enrichment, and naming.",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "server.js",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsup",
    "clean": "rm -rf dist",
    "test": "node --import tsx/esm --test tests/*.test.ts",
    "prepublishOnly": "npm run clean && npm run build && npm test"
  },
  "dependencies": {
    "zod": "^4.4.3"
  },
  "devDependencies": {
    "@opencode/plugin": "2.0.12",
    "@types/node": "^22.19.19",
    "tsup": "^8.5.1",
    "tsx": "^4.22.3",
    "typescript": "^5.9.3"
  },
  "engines": {
    "node": ">=22.22.3"
  },
  "license": "MIT",
  "author": "OmniRoute contributors",
  "repository": {
    "type": "git",
    "url": "https://github.com/diegosouzapw/OmniRoute.git",
    "directory": "@omniroute/opencode-plugin-v2"
  },
  "homepage": "https://github.com/diegosouzapw/OmniRoute/tree/main/%40omniroute/opencode-plugin-v2#readme",
  "bugs": {
    "url": "https://github.com/diegosouzapw/OmniRoute/issues"
  },
  "keywords": [
    "omniroute",
    "opencode",
    "opencode-plugin",
    "opencode-v2",
    "ai-sdk",
    "openai-compatible",
    "provider",
    "catalog",
    "combos",
    "gemini"
  ],
  "publishConfig": {
    "access": "public"
  },
  "peerDependencies": {
    "@opencode/plugin": ">=2.0.12 <3"
  },
  "overrides": {
    "esbuild": "^0.28.1"
  }
}
